-- Hand-written (D1): at most one live owner. Partial unique index over a
-- constant: a second non-deleted account with role_slug 'owner' conflicts.
CREATE UNIQUE INDEX "accounts_single_owner_uq" ON "accounts" ((1))
  WHERE "role_slug" = 'owner' AND "deleted_at" IS NULL;

-- Hand-written (SPEC §6, D6): system roles have fixed slug/rank pairs;
-- custom roles use ranks 11-39.
ALTER TABLE "roles" ADD CONSTRAINT "roles_rank_ck" CHECK (
  CASE WHEN "is_system"
    THEN ("slug", "rank") IN (
      ('public', 0), ('guest', 10), ('reviewer', 20),
      ('editor', 30), ('admin', 40), ('owner', 100))
    ELSE "rank" BETWEEN 11 AND 39
  END
);

-- Hand-written (D6): system roles are immutable (slug, rank, is_system) and
-- cannot be deleted; a custom role cannot become a system role.
CREATE FUNCTION "roles_protect_system"() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD."is_system" THEN
      RAISE EXCEPTION 'system role "%" cannot be deleted', OLD."slug"
        USING ERRCODE = 'integrity_constraint_violation';
    END IF;
    RETURN OLD;
  END IF;
  IF NEW."is_system" IS DISTINCT FROM OLD."is_system"
    OR (OLD."is_system" AND (NEW."slug" IS DISTINCT FROM OLD."slug"
      OR NEW."rank" IS DISTINCT FROM OLD."rank")) THEN
    RAISE EXCEPTION 'slug, rank and is_system of system role "%" are immutable', OLD."slug"
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  RETURN NEW;
END;
$$;

CREATE TRIGGER "roles_protect_system"
  BEFORE UPDATE OR DELETE ON "roles"
  FOR EACH ROW EXECUTE FUNCTION "roles_protect_system"();
